%% animate.m
%
% Description:
%   This function produces an animation based on a series of configuration
%   matrices Twb{k} corresponding to evenly-spaced times t(k).
%
% Inputs:
%   Twb_list: a cell array of Twb, the configuration of the body's CoM
%        frame {b} relative to the world frame {w}, represented as a 4x4 
%        homogeneous transformation matrix, i.e., an element of SE(3).
%   t_list: an array of evenly-spaced times corresponding to each entry in
%        Twb_list.
%   params: a struct with many fields, generated by calling init_params().
%
% Outputs:
%   none

function animate(Twb_list,t_list,params)
%% Compute outer bounds on plot size
% extract minima and maxima of CoM position in {w} from Twb_list:
Twb_mat = reshape(cell2mat(Twb_list),[4,4,numel(t_list)]);
pwb_list = squeeze(Twb_mat(1:3,4,:));
xwb_min = min(pwb_list(1,:));
xwb_max = max(pwb_list(1,:));
ywb_min = min(pwb_list(2,:));
ywb_max = max(pwb_list(2,:));
zwb_min = min(pwb_list(3,:));
zwb_max = max(pwb_list(3,:));

semi_axis_max = max([params.geom.ellipsoid.semi_axes.a,...
                     params.geom.ellipsoid.semi_axes.b,...
                     params.geom.ellipsoid.semi_axes.c]);

bounds3 = [xwb_min - params.viz.margin_scale*semi_axis_max,...
           xwb_max + params.viz.margin_scale*semi_axis_max,...
           ywb_min - params.viz.margin_scale*semi_axis_max,...
           ywb_max + params.viz.margin_scale*semi_axis_max,...
           zwb_min - params.viz.margin_scale*semi_axis_max,...
           zwb_max + params.viz.margin_scale*semi_axis_max];

%% Animate by plotting frame-by-frame
fig = figure;
set(fig,'position',[0,0,1920,1080])
ax = gca;

dt = t_list(2) - t_list(1); % TODO: use this when rendering videos

for k = 1:numel(t_list)
    plot_ellipsoid(ax,Twb_list{k},bounds3,params);
    hold on
    plot_ground(ax,bounds3,params);
    hold off
    
    axis equal
    axis(bounds3);
    xlabel('$x_\mathrm{w}$')
    ylabel('$y_\mathrm{w}$')
    zlabel('$z_\mathrm{w}$')
    drawnow;
end

end